  $('#gpsForm')?.addEventListener('submit', grantGps);
  $$('[data-revoke-gps]').forEach((button) => button.addEventListener('click', () => revokeGps(button)));
  $$('.store-form').forEach((form) => form.addEventListener('submit', saveStore));
